package com.bank.chaos.controller;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

// The chaos control plane. In production this is Chaos Mesh YAML or the
// Gremlin API. Here it is a tiny switchboard the demo can flip on and off.
public class ChaosController {
    private final AtomicBoolean networkLatency = new AtomicBoolean(false);
    private final AtomicBoolean cpuThrottle    = new AtomicBoolean(false);
    private final AtomicInteger networkLatencyMs = new AtomicInteger(200);
    private final AtomicInteger cpuThrottleMs    = new AtomicInteger(150);

    // NetworkChaos delay=200ms between service and PostgreSQL.
    public void injectNetworkLatency(int ms) {
        networkLatencyMs.set(ms);
        networkLatency.set(true);
    }

    // StressChaos pinning CPU so each task burns extra cycles.
    public void injectCpuThrottle(int ms) {
        cpuThrottleMs.set(ms);
        cpuThrottle.set(true);
    }

    // The MTTR phase removes all faults; a healthy system recovers on its own.
    public void clearAll() {
        networkLatency.set(false);
        cpuThrottle.set(false);
    }

    public int networkLatencyMs() { return networkLatency.get() ? networkLatencyMs.get() : 0; }
    public int cpuThrottleMs()    { return cpuThrottle.get()    ? cpuThrottleMs.get()    : 0; }
}
