package com.bank.chaos.service;

import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

// A tiny stand-in for HikariCP. A Semaphore models the finite connections.
// When downstream latency rises, borrowers block here and the pool drains.
public class ConnectionPool {
    private final Semaphore permits;
    private final int size;

    public ConnectionPool(int size) {
        this.size = size;
        this.permits = new Semaphore(size, true);
    }

    // Throws if we cannot borrow a connection in time — the pool-exhaustion signal.
    public void borrow(long timeoutMs) throws InterruptedException {
        boolean got = permits.tryAcquire(timeoutMs, TimeUnit.MILLISECONDS);
        if (!got) {
            throw new IllegalStateException("Connection is not available, request timed out");
        }
    }

    public void release() { permits.release(); }

    public int activeConnections() { return size - permits.availablePermits(); }
}
