package com.bank.chaos.service;

import com.bank.chaos.controller.ChaosController;
import com.bank.chaos.model.SettlementRequest;
import com.bank.chaos.telemetry.SliRecorder;

import java.util.concurrent.*;

// Processes settlements on a BOUNDED worker pool. The bounded queue plus a
// CallerRunsPolicy applies back-pressure instead of allocating forever when
// a CPU throttle slows the workers. This is the key resilience design.
public class SettlementService {
    private final ThreadPoolExecutor executor;
    private final ConnectionPool pool;
    private final ChaosController chaos;
    private final SliRecorder sli;

    public SettlementService(int workers, int queueCapacity, ConnectionPool pool,
                             ChaosController chaos, SliRecorder sli) {
        this.pool  = pool;
        this.chaos = chaos;
        this.sli   = sli;
        this.executor = new ThreadPoolExecutor(
                workers, workers, 0L, TimeUnit.MILLISECONDS,
                new ArrayBlockingQueue<>(queueCapacity),
                new NamedThreadFactory("settle-worker"),
                new ThreadPoolExecutor.CallerRunsPolicy()); // back-pressure
    }

    public void submit(SettlementRequest req) {
        long enqueuedAt = System.nanoTime();
        sli.recordQueueDepth(executor.getQueue().size());
        executor.execute(() -> process(req, enqueuedAt));
    }

    private void process(SettlementRequest req, long enqueuedAt) {
        try {
            // CPU throttle: burn cycles to mimic a starved pod.
            int burn = chaos.cpuThrottleMs();
            if (burn > 0) busyWait(burn);

            // Borrow a DB connection. Network latency delays the "query".
            pool.borrow(500);
            try {
                int lat = chaos.networkLatencyMs();
                if (lat > 0) Thread.sleep(lat); // simulated slow DB round-trip
                // ... real code would debit/credit here with BigDecimal ...
            } finally {
                pool.release();
            }
            long latencyMs = (System.nanoTime() - enqueuedAt) / 1_000_000;
            sli.recordSuccess(latencyMs);
            sli.recordActiveConnections(pool.activeConnections());
        } catch (IllegalStateException poolTimeout) {
            sli.recordError(); // pool exhaustion surfaced as an error SLI
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            sli.recordError();
        }
    }

    private void busyWait(long ms) {
        long end = System.nanoTime() + ms * 1_000_000L;
        while (System.nanoTime() < end) { /* steal CPU */ }
    }

    public void shutdown() throws InterruptedException {
        executor.shutdown();
        executor.awaitTermination(30, TimeUnit.SECONDS);
    }
}

// ─── Would be in NamedThreadFactory.java in a real project ───
class NamedThreadFactory implements ThreadFactory {
    private final String prefix;
    private int counter = 1;
    NamedThreadFactory(String prefix) { this.prefix = prefix; }
    public synchronized Thread newThread(Runnable r) {
        // pool-name-thread-N convention so stack dumps are readable.
        return new Thread(r, prefix + "-thread-" + counter++);
    }
}
