package com.bank.chaos.telemetry;

import java.util.concurrent.atomic.AtomicLong;

// Collects the Service Level Indicators the chaos experiment watches.
// A real system would export these to Prometheus; here we keep counters.
public class SliRecorder {
    private final AtomicLong success = new AtomicLong();
    private final AtomicLong errors  = new AtomicLong();
    private volatile long maxLatencyMs = 0;
    private volatile int maxQueueDepth = 0;
    private volatile int maxActiveConnections = 0;

    public void recordSuccess(long latencyMs) {
        success.incrementAndGet();
        if (latencyMs > maxLatencyMs) maxLatencyMs = latencyMs;
    }
    public void recordError() { errors.incrementAndGet(); }
    public void recordQueueDepth(int d) { if (d > maxQueueDepth) maxQueueDepth = d; }
    public void recordActiveConnections(int a) { if (a > maxActiveConnections) maxActiveConnections = a; }

    public double errorRatePct() {
        long total = success.get() + errors.get();
        return total == 0 ? 0 : (errors.get() * 100.0) / total;
    }
    public long maxLatencyMs() { return maxLatencyMs; }
    public int maxQueueDepth() { return maxQueueDepth; }
    public int maxActiveConnections() { return maxActiveConnections; }
    public long successCount() { return success.get(); }
    public long errorCount()   { return errors.get(); }
}
