package com.bank.chaos.load;

import com.bank.chaos.model.SettlementRequest;
import com.bank.chaos.service.SettlementService;

import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicInteger;

// Drives the four phases: step ramp, spike, MTTR window, and a short soak.
public class LoadDriver {
    private final SettlementService service;
    private final AtomicInteger seq = new AtomicInteger();

    public LoadDriver(SettlementService service) { this.service = service; }

    // Open-model arrival: fire N requests spaced by the target rate.
    public void fire(int count, int ratePerSec) throws InterruptedException {
        long gapNs = 1_000_000_000L / Math.max(ratePerSec, 1);
        for (int i = 0; i < count; i++) {
            int n = seq.incrementAndGet();
            service.submit(new SettlementRequest(
                    "TRD-" + n, "SAV2001", new BigDecimal("50000")));
            long next = System.nanoTime() + gapNs;
            while (System.nanoTime() < next) { /* pace arrivals */ }
        }
    }
}
