package com.bank.chaos;

import com.bank.chaos.controller.ChaosController;
import com.bank.chaos.load.LoadDriver;
import com.bank.chaos.service.ConnectionPool;
import com.bank.chaos.service.SettlementService;
import com.bank.chaos.telemetry.SliRecorder;

import java.util.logging.*;

// Runnable demo: step -> spike (with faults) -> MTTR -> short soak.
public class ChaosLoadDemo {
    private static final Logger log = Logger.getLogger(ChaosLoadDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        SliRecorder sli = new SliRecorder();
        ConnectionPool pool = new ConnectionPool(10);
        ChaosController chaos = new ChaosController();
        SettlementService service = new SettlementService(10, 100, pool, chaos, sli);
        LoadDriver driver = new LoadDriver(service);

        log.info("STEP phase: ramp load, no faults");
        driver.fire(200, 500);
        driver.fire(400, 1000);

        log.warning("SPIKE phase: inject network latency 200ms + CPU throttle 150ms");
        chaos.injectNetworkLatency(200);
        chaos.injectCpuThrottle(150);
        driver.fire(600, 2000); // burst while broken

        log.info("MTTR phase: clear faults, measure recovery");
        chaos.clearAll();
        driver.fire(300, 1000);

        log.info("SOAK phase (shortened): steady load to watch for creep");
        for (int cycle = 0; cycle < 5; cycle++) driver.fire(100, 500);

        service.shutdown();
        log.info(() -> String.format(
                "SLIs -> success=%d errors=%d errorRate=%.2f%% p-max-latency=%dms "
                + "maxQueueDepth=%d maxActiveConns=%d",
                sli.successCount(), sli.errorCount(), sli.errorRatePct(),
                sli.maxLatencyMs(), sli.maxQueueDepth(), sli.maxActiveConnections()));
    }
}

