package com.bank.chaos;

import com.bank.chaos.controller.ChaosController;
import com.bank.chaos.load.LoadDriver;
import com.bank.chaos.service.ConnectionPool;
import com.bank.chaos.service.SettlementService;
import com.bank.chaos.telemetry.SliRecorder;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ChaosLoadHarnessTest {

    @Test
    void steadyStateMeetsSlo() throws Exception {
        SliRecorder sli = new SliRecorder();
        SettlementService svc = new SettlementService(
                10, 100, new ConnectionPool(10), new ChaosController(), sli);
        new LoadDriver(svc).fire(300, 1000);
        svc.shutdown();
        assertTrue(sli.errorRatePct() < 1.0, "no-fault error rate must stay under SLO");
        assertEquals(0, sli.errorCount(), "steady state should not error");
    }

    @Test
    void networkLatencyExhaustsPoolButSystemStaysUp() throws Exception {
        SliRecorder sli = new SliRecorder();
        ChaosController chaos = new ChaosController();
        SettlementService svc = new SettlementService(
                20, 200, new ConnectionPool(5), chaos, sli);
        chaos.injectNetworkLatency(400);           // slow DB
        new LoadDriver(svc).fire(400, 4000);         // hammer it
        svc.shutdown();
        // The pool should max out, proving the saturation SLI fires.
        assertTrue(sli.maxActiveConnections() >= 4, "pool should saturate under latency");
        // But the service must still complete work, not deadlock.
        assertTrue(sli.successCount() > 0, "system must keep serving under fault");
    }

    @Test
    void mttrRecoversToBaselineAfterFaultCleared() throws Exception {
        SliRecorder sli = new SliRecorder();
        ChaosController chaos = new ChaosController();
        SettlementService svc = new SettlementService(
                10, 100, new ConnectionPool(10), chaos, sli);
        chaos.injectCpuThrottle(100);
        new LoadDriver(svc).fire(100, 1000);
        chaos.clearAll();                            // MTTR: remove fault
        long before = sli.successCount();
        new LoadDriver(svc).fire(100, 1000);
        svc.shutdown();
        assertTrue(sli.successCount() > before, "throughput must resume after recovery");
    }
}
